def read_readings(path):
    readings = []
    try:
        with open(path, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                time, litres = line.split()
                readings.append((time, int(litres)))
    except FileNotFoundError:
        return []
    return readings


def lowest(path):
    readings = read_readings(path)
    if not readings:
        return None
    return min(readings, key=lambda r: r[1])

