import csv


def totals_by_farmer(path):
    totals = {}
    with open(path, newline="", encoding="utf-8") as f:
        for row in csv.DictReader(f):
            name = row["farmer"]
            totals[name] = totals.get(name, 0.0) + float(row["kg"])
    return totals


def write_summary(in_path, out_path):
    totals = totals_by_farmer(in_path)
    with open(out_path, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["farmer", "total_kg"])
        for name in sorted(totals):
            w.writerow([name, totals[name]])
    return len(totals)

