exercises.solution:
import json


def new_game():
    return {"level": 1, "score": 0, "inventory": []}


def save_game(state, path):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(state, f, indent=2)


def load_game(path):
    try:
        with open(path, encoding="utf-8") as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return new_game()

